14	    [data-testid="job-item"] { border: 1px solid #ccc; border-radius: 6px; padding: 0.6rem 0.8rem; margin-bottom: 0.5rem; display: grid; grid-template-columns: 7rem 4rem 1fr; gap: 0.5rem; }
15	    .job-input { grid-column: 1 / -1; color: #555; font-size: 0.85rem; word-break: break-all; }
16	  </style>
17	</head>
18	<body>
19	  <h1>Job tracker</h1>
20	
21	  <form data-testid="job-form" id="job-form" novalidate>
22	    <label>Input
23	      <input data-testid="job-input" name="input" type="text" autocomplete="off">
24	    </label>
25	    <label>Steps
26	      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
27	    </label>
28	    <label>Fail attempts
29	      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
30	    </label>
31	    <button data-testid="job-submit" type="submit">Submit job</button>
32	  </form>
33	
34	  <div data-testid="form-error" role="alert" id="form-error"></div>
35	
36	  <ul data-testid="job-list" id="job-list"></ul>
37	
38	  <script>
39	    const form = document.getElementById('job-form');
40	    const inputEl = document.querySelector('[data-testid="job-input"]');
41	    const stepsEl = document.querySelector('[data-testid="job-steps"]');
42	    const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
43	    const submitBtn = document.querySelector('[data-testid="job-submit"]');
44	    const errorBox = document.querySelector('[data-testid="form-error"]');
45	    const list = document.querySelector('[data-testid="job-list"]');
46	
47	    // Numeric fields are sent as numbers; anything else is sent as typed so the API can reject it.
48	    function fieldValue(raw) {
49	      const trimmed = raw.trim();
50	      if (trimmed === '') return undefined;
51	      const n = Number(trimmed);
52	      return Number.isFinite(n) ? n : trimmed;
53	    }
54	
55	    function describeRejection(status, data) {
56	      const err = data && data.error;
57	      if (!err) return 'Request failed with status ' + status + '.';
58	      let text = err.message || 'Request rejected.';
59	      if (Array.isArray(err.fields) && err.fields.length > 0) {
60	        text += ' ' + err.fields.map((f) => f.field + ': ' + f.message).join('; ');
61	      }
62	      return text;
63	    }
64	
65	    function span(testid, text) {
66	      const el = document.createElement('span');
67	      if (testid) el.dataset.testid = testid;
68	      el.textContent = text;
69	      return el;
70	    }
71	
72	    function renderJob(job) {
73	      const li = document.createElement('li');
74	      li.dataset.testid = 'job-item';
75	      li.dataset.jobId = job.id;
76	      const result = job.status === 'completed' ? job.result.output : job.status === 'failed' ? job.error : '';
77	      li.append(
78	        span('job-status', job.status),
79	        span('job-progress', job.progress.completed + '/' + job.progress.total),
80	        span('job-result', result || ''),
81	      );
82	      const input = document.createElement('div');
83	      input.className = 'job-input';
84	      input.textContent = 'input: ' + job.input;
85	      li.append(input);
86	      return li;
87	    }
88	
89	    async function refresh() {
90	      try {
91	        const res = await fetch('/api/jobs', { cache: 'no-store' });
92	        if (!res.ok) return;
93	        const { jobs } = await res.json();
94	        list.replaceChildren(...jobs.map(renderJob));
95	      } catch {
96	        // The next poll retries.
97	      }
98	    }
99	
100	    form.addEventListener('submit', async (event) => {
101	      event.preventDefault();
102	      const body = { input: inputEl.value };
103	      const steps = fieldValue(stepsEl.value);
104	      const failAttempts = fieldValue(failEl.value);
105	      if (steps !== undefined) body.steps = steps;
106	      if (failAttempts !== undefined) body.failAttempts = failAttempts;
107	
108	      submitBtn.disabled = true;
109	      try {
110	        const res = await fetch('/api/jobs', {
111	          method: 'POST',
112	          headers: { 'content-type': 'application/json' },
113	          body: JSON.stringify(body),
114	        });
115	        const data = await res.json().catch(() => null);
116	        if (res.ok) {
117	          errorBox.textContent = '';
118	          inputEl.value = '';
119	          await refresh();
120	        } else {
121	          errorBox.textContent = describeRejection(res.status, data);
122	        }
123	      } catch (e) {
124	        errorBox.textContent = 'Could not reach the server: ' + e.message;
125	      } finally {
126	        submitBtn.disabled = false;
127	      }
128	    });
129	
130	    refresh();
131	    setInterval(refresh, 1000);
132	  </script>
